import java.util.Scanner;

public class Main {
    static long[] ones = new long[17];

    static int compute(long n, int i) {
        int total = i * (int)(n / ones[i]);
        n %= ones[i];
        if (n == 0) return total;
        return total + Math.min(i + compute(ones[i] - n, i - 1), compute(n, i - 1));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ones[0] = 0;
        for (int idx = 1; idx < 17; ++idx) {
            ones[idx] = ones[idx - 1] * 10 + 1;
        }
        long number = scanner.nextLong();
        System.out.println(compute(number, 16));
        scanner.close();
    }
}
